from target_app.hmac_auth import verify_stripe_signature
from target_app.models import CreditLedger, OutboxEmail, Subscription, User, WebhookEvent
from target_app.schemas import StripeEvent
from target_app.side_effects import send_welcome_email


def process_stripe_webhook(session, raw_body: bytes, sig_header: str) -> dict:
    if not verify_stripe_signature(raw_body, sig_header):
        raise ValueError('Invalid Stripe signature')
    event = StripeEvent.model_validate_json(raw_body)
    evt_id = event.id
    evt_type = event.type
    created = event.created or 0
    existing = session.query(WebhookEvent).filter_by(event_id=evt_id).first()
    if existing is not None:
        return {'status': 'duplicate', 'event_id': evt_id}
    obj = event.data.object or {}
    if not isinstance(obj, dict):
        obj = {}
    customer_id = obj.get('customer')
    user = None
    found_by_customer = False
    if customer_id:
        user = session.query(User).filter_by(stripe_customer_id=customer_id).first()
        if user is not None:
            found_by_customer = True
    if user is None:
        sub_candidate = None
        if evt_type in ('customer.subscription.created', 'customer.subscription.deleted'):
            sub_candidate = obj.get('id')
        elif isinstance(obj.get('subscription'), str):
            sub_candidate = obj.get('subscription')
        if sub_candidate:
            existing_sub = session.get(Subscription, sub_candidate)
            if existing_sub is not None:
                user = session.get(User, existing_sub.user_id)
    if user is None:
        user_id = obj.get('client_reference_id')
        if not user_id:
            metadata = obj.get('metadata')
            if isinstance(metadata, dict):
                user_id = metadata.get('user_id')
        if user_id:
            user = session.get(User, user_id)
    if user is None:
        raise ValueError(f'Unknown Stripe customer: {customer_id}')
    if evt_type == 'checkout.session.completed' and customer_id and not found_by_customer:
        user.stripe_customer_id = customer_id
    elif customer_id and not getattr(user, 'stripe_customer_id', None):
        user.stripe_customer_id = customer_id
    if evt_type == 'checkout.session.completed':
        if not user.welcome_email_sent:
            existing_email = session.query(OutboxEmail).filter_by(user_id=user.id, template='welcome_pro').first()
            if existing_email is None:
                send_welcome_email(session, user.id, dedupe_key=f'welcome_pro:{user.id}')
            user.welcome_email_sent = 1
        if created >= (user.last_event_ts or 0):
            user.plan_tier = 'pro'
            user.last_event_ts = created
    elif evt_type in ('customer.subscription.created', 'customer.subscription.deleted'):
        is_created = evt_type == 'customer.subscription.created'
        desired_status = 'active' if is_created else 'canceled'
        desired_plan = 'pro' if is_created else 'canceled'
        sub_id = obj.get('id')
        if sub_id:
            try:
                period_end = int(obj.get('current_period_end') or 0)
            except Exception:
                period_end = 0
            sub = session.get(Subscription, sub_id)
            if sub is None:
                sub = Subscription(id=sub_id, user_id=user.id, stripe_customer_id=customer_id or user.stripe_customer_id, status=desired_status, current_period_end=period_end, last_event_ts=created)
                session.add(sub)
            else:
                if created >= (sub.last_event_ts or 0):
                    sub.status = desired_status
                    sub.last_event_ts = created
                if period_end > (sub.current_period_end or 0):
                    sub.current_period_end = period_end
        if created >= (user.last_event_ts or 0):
            user.plan_tier = desired_plan
            user.last_event_ts = created
    elif evt_type == 'invoice.paid':
        invoice_id = obj.get('id')
        if invoice_id:
            existing_ledger = session.query(CreditLedger).filter_by(invoice_id=invoice_id).first()
            if existing_ledger is None:
                session.add(CreditLedger(user_id=user.id, invoice_id=invoice_id, delta=100, reason='invoice.paid'))
                user.credit_balance = (user.credit_balance or 0) + 100
    session.add(WebhookEvent(event_id=evt_id, event_type=evt_type, created_ts=created, status='processed'))
    try:
        session.commit()
    except Exception:
        try:
            session.rollback()
        except Exception:
            pass
        existing_after = None
        try:
            existing_after = session.query(WebhookEvent).filter_by(event_id=evt_id).first()
        except Exception:
            try:
                session.rollback()
            except Exception:
                pass
            existing_after = None
        if existing_after is not None:
            return {'status': 'duplicate', 'event_id': evt_id}
        raise
    return {'status': 'processed', 'event_id': evt_id}

